L10_1.m_Face = "UNIT_IDLE"
L11_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L10_1.m_CharStrID = L11_1
L11_1 = "고철 더미, 양철 깡통, 기계장치의 마왕, 아시모프……."
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "鉄くず、ブリキ缶、機械装置の魔王、アシモフ……"
