L11_1.m_bWaitClick = true
L11_1.m_fWaitTime = 0
L12_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L11_1.m_CharStrID = L12_1
L12_1 = "녀석에게 이런저런 별명은 많지만, 사실 녀석의 실체는 분명하지 않습니다."
L11_1.m_Talk_KOREA = L12_1
L11_1.m_fTalkTime = 0.03
L12_1 = "様々な別名がありますが、その実態は明らかになっていません。"
L11_1.m_Talk_JPN = L12_1
L12_1 = "She goes by many names, but the truth is, no one really knows her true identity."
L11_1.m_Talk_ENG = L12_1
L12_1 = "那傢伙有各種各樣的綽號，但其實他的真面目並不明確。"
L11_1.m_Talk_TWN = L12_1
L12_1 = "那家伙有各种各样的绰号，但其实他的真面目并不明确。"
L11_1.m_Talk_SCN = L12_1
L12_1 = "She goes by many names, but the truth is, no one really knows her true identity."
L11_1.m_Talk_DEU = L12_1
L12_1 = "She goes by many names, but the truth is, no one really knows her true identity."
L11_1.m_Talk_FRA = L12_1
