L13_1 = "EP13_ACT1_STAGE3_END@96#Talk"
L12_1.m_CutScenKey_Talk = L13_1
L13_1 = 162
L12_1.m_CutScenProcessKey = L13_1
L12_1.m_CutScenID = 589
L12_1.m_CutScenStrID = "EP13_ACT1_STAGE3_END"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L13_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L12_1.m_CharStrID = L13_1
L13_1 = "그저 평소에는 우주를 부유하고 있다가, 어떤 특정한 조건을 트리거로 활동을 시작."
L12_1.m_Talk_KOREA = L13_1
L12_1.m_fTalkTime = 0.03
L13_1 = "普段はただ宇宙を浮遊するのみで、ある特定の条件をトリガーに活動を開始。"
L12_1.m_Talk_JPN = L13_1
L13_1 = "She normally just floats in space, until a specific condition triggers her into action."
L12_1.m_Talk_ENG = L13_1
L13_1 = "平時只是漂浮在宇宙中，觸發某些特定條件後開始活動。"
L12_1.m_Talk_TWN = L13_1
L13_1 = "平时只是漂浮在宇宙中，触发某些特定条件后开始活动。"
L12_1.m_Talk_SCN = L13_1
L13_1 = "She normally just floats in space, until a specific condition triggers her into action."
L12_1.m_Talk_DEU = L13_1
L13_1 = "She normally just floats in space, until a specific condition triggers her into action."
L12_1.m_Talk_FRA = L13_1
L13_1 = {}
L14_1 = "EP13_ACT1_STAGE3_END@97#Talk"
