L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L14_1 = "LEESOOYEON_COFFIN_NULL_NULL"
L13_1.m_CharStrID = L14_1
L14_1 = "자신의 사도를 지구로 내려 보내, 수단과 방법을 가리지 않고 무차별 학살을 저지르죠."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "自分の使徒を地球に送り、手段を問わず無差別に人間を殺します。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "She then sends her Apostle down to Earth, carrying out indiscriminate massacres by any means necessary."
L13_1.m_Talk_ENG = L14_1
L14_1 = "派遣自己的使徒到地球，不擇手段地進行無差別屠殺。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "派遣自己的使徒到地球，不择手段地进行无差别屠杀。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "She then sends her Apostle down to Earth, carrying out indiscriminate massacres by any means necessary."
L13_1.m_Talk_DEU = L14_1
L14_1 = "She then sends her Apostle down to Earth, carrying out indiscriminate massacres by any means necessary."
L13_1.m_Talk_FRA = L14_1
