L21_1 = "USER_ADMIN_NULL_NULL"
L20_1.m_CharStrID = L21_1
L21_1 = "기계가 기계로서의 사명을 다하듯."
L20_1.m_Talk_KOREA = L21_1
L20_1.m_fTalkTime = 0.03
L21_1 = "機械が機械としての使命を果たすように、"
L20_1.m_Talk_JPN = L21_1
L21_1 = "Just as a machine fulfills its purpose as a machine..."
L20_1.m_Talk_ENG = L21_1
L21_1 = "如同機器完成其作為機器的使命。"
L20_1.m_Talk_TWN = L21_1
L21_1 = "如同机器完成其作为机器的使命。"
L20_1.m_Talk_SCN = L21_1
L21_1 = "Just as a machine fulfills its purpose as a machine..."
L20_1.m_Talk_DEU = L21_1
L21_1 = "Just as a machine fulfills its purpose as a machine..."
L20_1.m_Talk_FRA = L21_1
L21_1 = {}
L22_1 = "EP13_ACT1_STAGE3_END@102#Talk"
L21_1.m_CutScenKey_Talk = L22_1
L22_1 = 171
L21_1.m_CutScenProcessKey = L22_1
L21_1.m_CutScenID = 589
L21_1.m_CutScenStrID = "EP13_ACT1_STAGE3_END"
L21_1.m_bWaitClick = true
L21_1.m_fWaitTime = 0
L22_1 = "USER_ADMIN_NULL_NULL"
L21_1.m_CharStrID = L22_1
L22_1 = "<color=#ffd34c>방주</color>가 방주로서 사명을 다할 뿐이라네, 미나 양."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "<color=#ffd34c>箱舟</color>もまた箱舟としての使命を果たしているだけさ、ミナ君。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "An <color=#ffd34c>Ark</color> is simply fulfilling its purpose as an Ark, Mina."
L21_1.m_Talk_ENG = L22_1
L22_1 = "<color=#ffd34c>方舟</color>只是盡其作為方舟的使命罷了，米娜。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "<color=#ffd34c>方舟</color>只是尽其作为方舟的使命罢了，米娜小姐。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "An <color=#ffd34c>Ark</color> is simply fulfilling its purpose as an Ark, Mina."
L21_1.m_Talk_DEU = L22_1
L22_1 = "An <color=#ffd34c>Ark</color> is simply fulfilling its purpose as an Ark, Mina."
L21_1.m_Talk_FRA = L22_1
L22_1 = {}
L23_1 = "EP13_ACT1_STAGE3_END@103#Talk"
L22_1.m_CutScenKey_Talk = L23_1
L23_1 = 172
L22_1.m_CutScenProcessKey = L23_1
L22_1.m_CutScenID = 589
L22_1.m_CutScenStrID = "EP13_ACT1_STAGE3_END"
L22_1.m_bWaitClick = true
L22_1.m_fWaitTime = 0
L23_1 = "USER_ADMIN_NULL_NULL"
L22_1.m_CharStrID = L23_1
L23_1 = "모든 인류를 구하는 것이 불가능하니, 구해야 하는 인간을 시험하고 선별하는 거지."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "全ての人類を救済することが不可能である以上、救うべき人間を試し、選別する。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "Since saving all of humanity is impossible, she tests and selects those deemed worthy of salvation."
L22_1.m_Talk_ENG = L23_1
L23_1 = "既然無法拯救全人類，那就要考驗並篩選出需要拯救的人類。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "既然无法拯救全人类，那就要考验并筛选出需要拯救的人类。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "Since saving all of humanity is impossible, she tests and selects those deemed worthy of salvation."
L22_1.m_Talk_DEU = L23_1
L23_1 = "Since saving all of humanity is impossible, she tests and selects those deemed worthy of salvation."
L22_1.m_Talk_FRA = L23_1
L23_1 = {}
L24_1 = "EP13_ACT1_STAGE3_END@104#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 173
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 589
L23_1.m_CutScenStrID = "EP13_ACT1_STAGE3_END"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L24_1 = "USER_ADMIN_NULL_NULL"
L23_1.m_CharStrID = L24_1
L24_1 = "애초에 마왕 아시모프의 정체는 <color=#ffd34c>코핀 오브 릴리스</color>의 네비게이션 시스템이거든."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "そもそも魔王アシモフの正体とは、<color=#ffd34c>コフィン・オブ・リリス</color>のナビゲーションシステムだからね。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "The Demon Lord Asimov is actually the navigation system of the <color=#ffd34c>Coffin of Lilith</color>."
L23_1.m_Talk_ENG = L24_1
L24_1 = "本來魔王阿西莫夫的真面目就是<color=#ffd34c>科芬·莉莉絲</color>的導航系統。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "本来魔王阿西莫夫的真面目就是<color=#ffd34c>科芬·欧布·莉莉丝</color>的导航系统。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "The Demon Lord Asimov is actually the navigation system of the <color=#ffd34c>Coffin of Lilith</color>."
