L29_1.m_CharStrID = L30_1
L30_1 = "아니, 각 마왕을 봉인하는 코핀 함의 메인 프레임은 기본적으로 동일한 구조라네."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "いや、各魔王を封印するコフィン艦のメインフレームは、基本的に同じ構造をしている。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "Not quite. The mainframe of the Coffin that seals each Demon Lord is built on the same structure."
L29_1.m_Talk_ENG = L30_1
