L30_1.m_CharStrID = L31_1
L31_1 = "아마도 저건 마왕이 된 이후에 스스로를 보다 더 방주에 걸맞은 형태로 개조한 것이겠지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "おそらくあれは、魔王になってから自分をより箱舟に相応しい形に改造したのだろう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "That one likely modified herself after becoming a Demon Lord to better resemble an Ark."
