L34_1 = "녀석이 클리포트 마왕인 이상, 어떤 형태든, 어떤 목적을 가졌든… 그런 건 중요하지 않아."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "やつがクリフォトの魔王である以上、どんな形で、どんな目的を持っているかはどうでもいい。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "It doesn't matter what form she takes or what goal she has, as long as she's a Demon Lord of Qliphoth."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那傢伙既然是逆卡巴拉遊戲魔王，不管是什麼形態，什麼目的……那些都不重要。"
L33_1.m_Talk_TWN = L34_1
L34_1 = "那家伙既然是神圣战役魔王，不管是什么形态，什么目的……那些都不重要。"
L33_1.m_Talk_SCN = L34_1
L34_1 = "It doesn't matter what form she takes or what goal she has, as long as she's a Demon Lord of Qliphoth."
L33_1.m_Talk_DEU = L34_1
L34_1 = "It doesn't matter what form she takes or what goal she has, as long as she's a Demon Lord of Qliphoth."
