L34_1.m_CharStrID = L35_1
L34_1.m_Pos = "C"
L35_1 = "중요한 건, 녀석이 이 세계에 모습을 드러낸 이상, 싸워야 할 적이라는 거다."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "重要なのは、やつがこの世界に姿を現した以上、戦うべき敵だということだ。"
L34_1.m_Talk_JPN = L35_1
L35_1 = "What does matter is that she appeared in this world and that makes her our enemy."
L34_1.m_Talk_ENG = L35_1
L35_1 = "重要的是，既然那傢伙已經在這個世界現身了，那就是我們必須與之戰鬥的敵人。"
L34_1.m_Talk_TWN = L35_1
L35_1 = "重要的是，既然那家伙已经在这个世界现身了，那就是我们必须与之战斗的敌人。"
L34_1.m_Talk_SCN = L35_1
L35_1 = "What does matter is that she appeared in this world and that makes her our enemy."
