L42_1 = "클리파가 봉인되어 있다고 해도, 아시모프는 얼마든지 인류를 멸망시킬 방법을 알고 있을 테니까."
L41_1.m_Talk_KOREA = L42_1
L41_1.m_fTalkTime = 0.03
L42_1 = "クリファが封印されているとはいえ、アシモフはいくらでも人類を滅亡させる方法を知っているはずだからね。"
L41_1.m_Talk_JPN = L42_1
