L41_1.m_Talk_ENG = L42_1
L42_1 = "即使逆卡巴拉被封印，阿西莫夫也一定知道毀滅人類的方法。"
L41_1.m_Talk_TWN = L42_1
L42_1 = "即使逆卡巴拉被封印，阿西莫夫也一定知道毁灭人类的方法。"
