L48_1 = "둘째, 모습을 드러낸 마왕이 어째서 일주일째 아무런 행동도 취하지 않고 있는 것인지……."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "2つ目、姿を現した魔王がどうして一週間も何も行動を起こさないのか……"
