L4_1 = "그 트리거를 알아낼 수 있다면, 고철 더미의 판단을 보류시킬 수도 있다는 말씀이시군요."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "そのトリガーさえ突き止めることができれば、鉄くずの判断を保留させるのも可能ということですね。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "So if we can identify that trigger, we might be able to delay her decision-making."
